/**
 * @distilled.cloud/iceberg — Apache Iceberg REST Catalog SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model in
 * `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * document mirrored at
 * `specs/spec-mirror-iceberg/specs/rest-catalog-open-api.yaml`). Everything
 * else in this folder is hand-written.
 *
 * One API for every Iceberg REST catalog — Cloudflare Basin Catalog, Apache
 * Polaris, Nessie, Unity Catalog, AWS Glue's and S3 Tables' Iceberg
 * endpoints, the reference REST catalog. Operations are re-exported at the
 * package root. The warehouse `prefix` is credentials configuration (see
 * `fromCatalogConfig`), not an operation input.
 *
 * Multipart namespaces are one string with parts separated by the unit
 * separator: `["accounting", "tax"]` is `"accounting\u001ftax"`.
 *
 * @example
 * ```ts
 * import * as Iceberg from "@distilled.cloud/iceberg";
 *
 * yield* Iceberg.createNamespace({ namespace: ["analytics"] });
 * const { identifiers } = yield* Iceberg.listTables({ namespace: "analytics" });
 * ```
 */
